96:    * Unregister shortcut by ShortcutId
97:    * @param shortcutId
98:    */
99:   unregisterShortcut(shortcutId) {
100:     this.shortcuts.forEach((shortcut, i) => {
101:       if (shortcut.id === shortcutId) {
102:         this.shortcuts.splice(i, 1);
103:       }
104:     });
105:   }
